#requires -Version 5.1
<#!
KIT PROFISSIONAL DE DIAGNOSTICO WINDOWS V2.0
Windows 10/11 - PowerShell 5.1
Somente leitura por padrao; operacoes destrutivas exigem confirmacao.
#>
Set-StrictMode -Version 2.0
$ErrorActionPreference='SilentlyContinue'
$Desktop=[Environment]::GetFolderPath('Desktop')
$ReportRoot=Join-Path $Desktop 'Diagnosticos_PC'
$History=Join-Path $ReportRoot 'Historico_Diagnosticos.txt'
$Findings=New-Object System.Collections.ArrayList

function Init {
 if(!(Test-Path -LiteralPath $ReportRoot)){New-Item -ItemType Directory -Path $ReportRoot -Force|Out-Null}
 if(!(Test-Path -LiteralPath $History)){Set-Content $History 'HISTORICO DE DIAGNOSTICOS' -Encoding UTF8}
}
function Admin {try{$id=[Security.Principal.WindowsIdentity]::GetCurrent();$p=New-Object Security.Principal.WindowsPrincipal($id);return $p.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)}catch{return $false}}
function Cim($class,$ns='root/cimv2'){try{@(Get-CimInstance -Namespace $ns -ClassName $class -ErrorAction Stop)}catch{@()}}
function Add-Finding([string]$s,[string]$m,[string]$r=''){[void]$Findings.Add([pscustomobject]@{Status=$s;Message=$m;Recommendation=$r})}
function Status {if(@($Findings|? Status -eq 'CRITICO').Count){'CRITICO'}elseif(@($Findings|? Status -eq 'ERRO').Count){'ERRO'}elseif(@($Findings|? Status -eq 'ATENCAO').Count){'ATENCAO'}else{'OK'}}
function Report([string]$name,[string]$desc,[string[]]$results,[string[]]$analysis){$st=Status;$safe=$name -replace '[^\w-]','_';$file=Join-Path $ReportRoot ('{0}_{1}.txt'-f(Get-Date -Format 'yyyy-MM-dd_HH-mm-ss'),$safe);$s=Cim 'Win32_OperatingSystem'|select -First 1;$c=Cim 'Win32_ComputerSystem'|select -First 1;$lines=@('============================================================','RELATORIO DE DIAGNOSTICO','============================================================',"Data: $(Get-Date -Format 'dd/MM/yyyy HH:mm:ss')","Computador: $env:COMPUTERNAME","Usuario: $env:USERNAME","Windows: $($s.Caption) Build $($s.BuildNumber)","Modelo: $($c.Manufacturer) $($c.Model)","Administrador: $(if(Admin){'SIM'}else{'NAO'})",'',"TESTE: $name","DESCRICAO: $desc",'','------------------------------------------------------------','RESULTADOS','------------------------------------------------------------')+$results+@('','------------------------------------------------------------','ANALISE','------------------------------------------------------------')+$analysis+@('','------------------------------------------------------------','STATUS','------------------------------------------------------------',"[$st]",'','RECOMENDACAO','------------------------------------------------------------');$recs=@($Findings|? Recommendation|select -Expand Recommendation -Unique);if($recs){$lines+=$recs|%{"- $_"}}else{$lines+='Nenhuma recomendacao adicional.'};$lines+=@('','============================================================','FIM DO RELATORIO','============================================================');$lines|Set-Content -LiteralPath $file -Encoding UTF8;Add-Content $History ("$(Get-Date -Format 'dd/MM/yyyy HH:mm:ss') | $name | $st | $file") -Encoding UTF8;Write-Host "Status: [$st]";Write-Host "Relatorio: $file" -ForegroundColor Cyan;Write-Host ("OK: {0} | ATENCAO: {1} | ERROS: {2} | CRITICOS: {3}"-f @($Findings|? Status -eq 'OK').Count,@($Findings|? Status -eq 'ATENCAO').Count,@($Findings|? Status -eq 'ERRO').Count,@($Findings|? Status -eq 'CRITICO').Count);Read-Host 'ENTER para voltar'|Out-Null}
function Run([scriptblock]$x){$Findings.Clear();try{&$x}catch{Add-Finding 'ERRO' $_.Exception.Message};if($script:Full){return}}
function Test-Inventory {$os=Cim Win32_OperatingSystem|select -First 1;$cs=Cim Win32_ComputerSystem|select -First 1;$cpu=Cim Win32_Processor|select -First 1;$bios=Cim Win32_BIOS|select -First 1;$r=@("Fabricante/Modelo: $($cs.Manufacturer) / $($cs.Model)","Serie: $($bios.SerialNumber)","CPU: $($cpu.Name)","Nucleos/Threads: $($cpu.NumberOfCores)/$($cpu.NumberOfLogicalProcessors)","RAM: $([math]::Round($cs.TotalPhysicalMemory/1GB,2)) GB","Windows: $($os.Caption) $($os.Version) Build $($os.BuildNumber)","Uptime: $((Get-Date)-$os.LastBootUpTime)");Add-Finding OK 'Inventario coletado';Report 'Inventario_Hardware' 'Inventario basico do equipamento.' $r @('Coleta somente informacoes do sistema.')}
function Test-CPU {$cpu=Cim Win32_Processor|select -First 1;$p=Cim Win32_PerfFormattedData_PerfOS_Processor|? Name -eq '_Total'|select -First 1;$u=[double]$p.PercentProcessorTime;$r=@("Modelo: $($cpu.Name)","Nucleos: $($cpu.NumberOfCores)","Threads: $($cpu.NumberOfLogicalProcessors)","Uso instantaneo: $u%",'TOP PROCESSOS:');$r+=Get-Process|sort CPU -Descending|select -First 10|%{"$($_.ProcessName) | PID $($_.Id) | RAM $([math]::Round($_.WorkingSet64/1MB)) MB"};if($u -ge 90){Add-Finding ATENCAO "CPU elevada: $u%" 'Investigar processos e carga persistente.'}else{Add-Finding OK "CPU em $u%"};Report 'Diagnostico_CPU' 'CPU e processos.' $r @('Amostra instantanea nao prova carga constante.')}
function Test-RAM {$os=Cim Win32_OperatingSystem|select -First 1;$cs=Cim Win32_ComputerSystem|select -First 1;$total=[double]$cs.TotalPhysicalMemory;$free=[double]$os.FreePhysicalMemory*1KB;$pct=[math]::Round((1-$free/$total)*100,1);$r=@("Total: $([math]::Round($total/1GB,2)) GB","Livre: $([math]::Round($free/1GB,2)) GB","Uso: $pct%");if($pct -ge 90){Add-Finding ATENCAO "RAM elevada: $pct%" 'Investigar processos e paginacao.'}else{Add-Finding OK "RAM em $pct%"};Report 'Diagnostico_RAM' 'Memoria RAM e utilizacao.' $r @('Coleta sem alterar memoria ou configuracoes.')}
function Test-Disk {$r=@();$vol=Get-Volume|? DriveLetter;foreach($v in $vol){$p=if($v.Size){[math]::Round($v.SizeRemaining/$v.Size*100,1)}else{0};$r+="$($v.DriveLetter): $([math]::Round($v.Size/1GB,2)) GB | Livre $p% | FS $($v.FileSystem) | Health $($v.HealthStatus)";if($p -lt 10){Add-Finding CRITICO "$($v.DriveLetter): com apenas $p% livre" 'Liberar espaco com autorizacao.'}elseif($p -lt 20){Add-Finding ATENCAO "$($v.DriveLetter): pouco espaco ($p%)" 'Planejar liberacao de espaco.'}else{Add-Finding OK "$($v.DriveLetter): espaco adequado"}};Report 'Diagnostico_Disco' 'Volumes, espaco e saude exposta pelo Windows.' $r @('Nenhum CHKDSK /F e executado automaticamente.')}
function Test-Windows {$s=&sfc.exe /verifyonly 2>&1|Out-String;$d=&DISM.exe /Online /Cleanup-Image /CheckHealth 2>&1|Out-String;$r=@('SFC /verifyonly:',$s,'','DISM /CheckHealth:',$d);if($s-match 'violations|violações'){Add-Finding ATENCAO 'SFC indicou possivel inconsistencia' 'Revisar antes de reparar.'}else{Add-Finding OK 'SFC executado sem indicio claro de violacao'};Report 'Integridade_Windows' 'SFC e DISM somente em modo de verificacao.' $r @('Nenhum reparo automatico foi executado.')}
function Test-Events {$since=(Get-Date).AddDays(-7);$ev=@(Get-WinEvent -FilterHashtable @{LogName='System';StartTime=$since;Level=1,2,3});$r=@("Eventos relevantes em 7 dias: $($ev.Count)");$r+=($ev|select -First 50|%{"$($_.TimeCreated) | ID $($_.Id) | $($_.ProviderName) | $($_.LevelDisplayName)"});if($ev.Count -gt 100){Add-Finding ATENCAO "Muitos eventos relevantes: $($ev.Count)" 'Investigar IDs e provedores recorrentes.'}else{Add-Finding OK "Eventos relevantes: $($ev.Count)"};Report 'Eventos_Windows' 'Eventos System dos ultimos 7 dias.' $r @('Eventos isolados nao determinam causa raiz.')}
function Test-Shutdown {$ev=@();foreach($id in 41,6008,1001){$ev+=@(Get-WinEvent -FilterHashtable @{LogName='System';Id=$id;StartTime=(Get-Date).AddDays(-30)})};$r=@("Eventos 41/6008/1001 em 30 dias: $($ev.Count)");$r+=($ev|select -Last 50|%{"$($_.TimeCreated) | ID $($_.Id) | $($_.ProviderName)"});if(@($ev|? Id -in 41,6008).Count){Add-Finding ATENCAO 'Foram encontrados registros de desligamento/reinicio inesperado' 'Correlacionar energia, fonte, travamentos e eventos.'}else{Add-Finding OK 'Nenhum 41/6008 encontrado'};Report 'Desligamentos_Incorretos' 'Eventos associados a reinicios e desligamentos.' $r @('Kernel-Power sozinho nao prova defeito de fonte.')}
function Test-Network {$a=Get-NetAdapter;$c=Get-NetIPConfiguration;$r=@();$r+=($a|%{"$($_.Name) | $($_.Status) | $($_.LinkSpeed) | $($_.MacAddress)"});foreach($x in $c|? IPv4Address){$r+="$($x.InterfaceAlias) | IP $($x.IPv4Address.IPAddress) | GW $($x.IPv4DefaultGateway.NextHop) | DNS $($x.DnsServer.ServerAddresses -join ',')"};$gw=($c|? IPv4DefaultGateway|select -First 1).IPv4DefaultGateway.NextHop;if($gw){if(Test-Connection $gw -Count 2){Add-Finding OK 'Gateway respondeu ao ping'}else{Add-Finding ERRO 'Gateway nao respondeu ao ping' 'Verificar rede local.'}}else{Add-Finding ERRO 'Gateway IPv4 nao encontrado' 'Verificar DHCP.'};$dns=Resolve-DnsName www.microsoft.com -ErrorAction SilentlyContinue;if($dns){Add-Finding OK 'DNS funcional'}else{Add-Finding ERRO 'DNS falhou' 'Verificar DNS.'};Report 'Diagnostico_Rede' 'Adaptadores, IP, gateway e DNS.' $r @('Testes somente de conectividade.')}
function Test-WiFi {$r=@((netsh wlan show interfaces));if($r -match 'Signal|Sinal'){Add-Finding OK 'Interface Wi-Fi consultada'}else{Add-Finding ATENCAO 'Nao foi possivel obter detalhes de Wi-Fi' 'Verificar adaptador/driver.'};Report 'Diagnostico_WiFi' 'Estado da interface Wi-Fi.' $r @('Saida depende do driver e estado da conexao.')}
function Test-Drivers {$d=@(Get-PnpDevice);$bad=@($d|? Status -ne 'OK');$r=@("PNP: $($d.Count)","Fora de OK: $($bad.Count)");$r+=($bad|select -First 100|%{"$($_.Class) | $($_.FriendlyName) | $($_.Status)"});if($bad.Count){Add-Finding ATENCAO "$($bad.Count) dispositivos fora de OK" 'Investigar cada dispositivo.'}else{Add-Finding OK 'Nenhum dispositivo PnP fora de OK'};Report 'Diagnostico_Drivers' 'Inventario PnP e indicios de erro.' $r @('Nenhum driver foi instalado ou alterado.')}
function Test-Processes {$p=@(Get-Process);$r=@("Processos: $($p.Count)",'TOP RAM:');$r+=($p|sort WorkingSet64 -Descending|select -First 20|%{"$($_.ProcessName) | PID $($_.Id) | RAM $([math]::Round($_.WorkingSet64/1MB)) MB"});Add-Finding OK 'Processos coletados';Report 'Diagnostico_Processos' 'Principais consumidores de memoria.' $r @('Uso alto nao significa automaticamente malware.')}
function Test-Startup {$x=@(Cim Win32_StartupCommand);$r=@("Entradas: $($x.Count)");$r+=($x|%{"$($_.Name) | $($_.Location) | $($_.Command)"});Add-Finding OK 'Inicializacao coletada';Report 'Inicializacao_Windows' 'Entradas de inicializacao.' $r @('Nenhuma entrada foi desativada.')}
function Test-Services {$s=@(Get-Service);$bad=@($s|? {$_.StartType -eq 'Automatic' -and $_.Status -eq 'Stopped'});$r=@("Servicos: $($s.Count)","Automaticos parados: $($bad.Count)");$r+=($bad|%{"$($_.DisplayName) | $($_.Status)"});if($bad.Count){Add-Finding ATENCAO "$($bad.Count) servicos automaticos parados" 'Avaliar somente os servicos relacionados ao problema.'}else{Add-Finding OK 'Nenhum servico automatico parado'};Report 'Servicos_Windows' 'Estado dos servicos sem alteracao.' $r @('Servicos nao sao iniciados/parados automaticamente.')}
function Test-Security {$r=@();try{$m=Get-MpComputerStatus;$r+="Defender: $($m.AntivirusEnabled) | RealTime: $($m.RealTimeProtectionEnabled)";if($m.AntivirusEnabled -and $m.RealTimeProtectionEnabled){Add-Finding OK 'Defender ativo'}else{Add-Finding ATENCAO 'Defender/protecao em tempo real nao plenamente ativo' 'Verificar se existe outro antivirus.'}}catch{Add-Finding ATENCAO 'Defender indisponivel' 'Pode existir outro produto de seguranca.'};try{$fw=Get-NetFirewallProfile;$r+=($fw|%{"Firewall $($_.Name): $($_.Enabled)"})}catch{};Report 'Seguranca' 'Defender e Firewall.' $r @('Nenhuma configuracao de seguranca foi alterada.')}
function Test-TPM {$r=@();try{$t=Get-Tpm;$r+="TPM presente: $($t.TpmPresent) | Pronto: $($t.TpmReady)";if($t.TpmPresent -and $t.TpmReady){Add-Finding OK 'TPM presente e pronto'}else{Add-Finding ATENCAO 'TPM ausente ou nao pronto' 'Verificar UEFI/BIOS.'}}catch{Add-Finding ATENCAO 'TPM indisponivel'};try{$r+="Secure Boot: $(Confirm-SecureBootUEFI)"}catch{$r+='Secure Boot: indisponivel'};Report 'TPM_SecureBoot' 'TPM e Secure Boot.' $r @('Nenhuma configuracao UEFI foi alterada.')}
function Test-GPU {$g=@(Cim Win32_VideoController);$r=@($g|%{"$($_.Name) | Driver $($_.DriverVersion) | Status $($_.Status) | Resolucao $($_.CurrentHorizontalResolution)x$($_.CurrentVerticalResolution)"});Add-Finding OK 'GPU coletada';Report 'GPU_Video' 'GPU e driver de video.' $r @('VRAM WMI pode ser aproximada em GPUs modernas.')}
function Test-Battery {$b=@(Cim Win32_Battery);$r=@();if(!$b){$r+='Nenhuma bateria detectada';Add-Finding OK 'Sem bateria detectada'}else{foreach($x in $b){$r+="$($x.Name) | Carga $($x.EstimatedChargeRemaining)% | Status $($x.Status)"};Add-Finding OK 'Bateria coletada'};Report 'Bateria_Notebook' 'Estado da bateria.' $r @('Nenhum ciclo de carga foi alterado.')}
function Test-Temp {$t=@(Cim MSAcpi_ThermalZoneTemperature 'root/wmi');$r=@();foreach($x in $t){$r+="Zona: $($x.InstanceName) | $([math]::Round($x.CurrentTemperature/10-273.15,1)) C"};if($t){Add-Finding OK 'Temperatura WMI coletada'}else{Add-Finding OK 'Sensor termico nao exposto pelo WMI'};Report 'Temperaturas' 'Temperatura quando exposta pelo WMI ACPI.' $r @('Ausencia de sensor nao e tratada como defeito.')}
function Test-TempFiles {$paths=@($env:TEMP,(Join-Path $env:windir 'Temp'));$sum=0;$r=@();foreach($p in $paths){$f=@(Get-ChildItem $p -File -Recurse -Force);$s=($f|measure Length -Sum).Sum;$sum+=$s;$r+="$p | $($f.Count) arquivos | $([math]::Round($s/1GB,2)) GB"};Add-Finding OK 'Temporarios apenas analisados';Report 'Arquivos_Temporarios' 'Analise de arquivos temporarios sem apagar nada.' $r @('Nenhum arquivo foi removido.')}
function Full {$script:Full=$true;try{$list=@('Inventory','CPU','RAM','Disk','Windows','Events','Shutdown','Network','WiFi','Drivers','Processes','Startup','Services','Security','TPM','GPU','Battery','Temp','TempFiles');foreach($n in $list){$Findings.Clear();switch($n){'Inventory'{Test-Inventory};'CPU'{Test-CPU};'RAM'{Test-RAM};'Disk'{Test-Disk};'Windows'{Test-Windows};'Events'{Test-Events};'Shutdown'{Test-Shutdown};'Network'{Test-Network};'WiFi'{Test-WiFi};'Drivers'{Test-Drivers};'Processes'{Test-Processes};'Startup'{Test-Startup};'Services'{Test-Services};'Security'{Test-Security};'TPM'{Test-TPM};'GPU'{Test-GPU};'Battery'{Test-Battery};'Temp'{Test-Temp};'TempFiles'{Test-TempFiles}}}}finally{$script:Full=$false}}
function Menu {while($true){Clear-Host;Write-Host '============================================================';Write-Host '       KIT PROFISSIONAL DE DIAGNOSTICO WINDOWS V2.0';Write-Host '============================================================';Write-Host "Computador: $env:COMPUTERNAME | Admin: $(if(Admin){'SIM'}else{'NAO'})";Write-Host '';Write-Host '[1] Completo  [2] Hardware  [3] CPU  [4] RAM  [5] Disco';Write-Host '[6] Windows   [7] Eventos  [8] Reinicios  [9] Rede';Write-Host '[10] Wi-Fi    [11] Drivers [12] Processos [13] Inicializacao';Write-Host '[14] Servicos [15] Seguranca [16] TPM/Secure Boot [17] GPU';Write-Host '[18] Bateria  [19] Temperaturas [20] Temporarios';Write-Host '[0] Sair';$c=Read-Host 'Digite';switch($c){'1'{Full};'2'{Run {Test-Inventory}};'3'{Run {Test-CPU}};'4'{Run {Test-RAM}};'5'{Run {Test-Disk}};'6'{Run {Test-Windows}};'7'{Run {Test-Events}};'8'{Run {Test-Shutdown}};'9'{Run {Test-Network}};'10'{Run {Test-WiFi}};'11'{Run {Test-Drivers}};'12'{Run {Test-Processes}};'13'{Run {Test-Startup}};'14'{Run {Test-Services}};'15'{Run {Test-Security}};'16'{Run {Test-TPM}};'17'{Run {Test-GPU}};'18'{Run {Test-Battery}};'19'{Run {Test-Temp}};'20'{Run {Test-TempFiles}};'0'{return};default{Write-Host 'Opcao invalida' -ForegroundColor Yellow;Start-Sleep 1}}}}
Init;Menu